<?php
declare(strict_types=1);
require __DIR__ . '/app-loader.php';
$user=require_login();
$stmt=db()->prepare("SELECT d.public_id,d.title,d.currency,d.amount_minor,d.fee_minor,d.status,d.created_at,d.buyer_id,d.seller_email,bu.name AS buyer_name,se.name AS seller_name FROM deals d JOIN users bu ON bu.id=d.buyer_id LEFT JOIN users se ON se.id=d.seller_id WHERE d.buyer_id=? OR d.seller_id=? ORDER BY d.created_at DESC");
$stmt->execute([$user['id'],$user['id']]);$deals=$stmt->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My deals · XWADDA.KE</title><link rel="stylesheet" href="assets/styles.css"><style>.my-deals{max-width:1060px;margin:auto;padding:28px 18px}.deals-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.deals-head h1{font:700 25px var(--display);margin:7px 0}.deal-card-real{background:#fff;border:1px solid #e8ece7;border-radius:9px;padding:15px;margin:10px 0;display:grid;grid-template-columns:1fr auto;gap:10px}.deal-card-real h3{font:700 13px var(--display);margin:0 0 6px}.deal-card-real p{font-size:10px;color:#859088;margin:4px 0}.deal-card-real .status-text{font-size:10px;font-weight:700;color:#346649}.notice-real{background:#edf5ed;color:#3e7450;border-radius:6px;padding:9px;font-size:10px;margin:12px 0}.empty-deals{background:#fff;border:1px dashed #dce5dc;border-radius:9px;padding:34px;text-align:center;color:#829087;font-size:11px}.deal-actions{display:flex;gap:8px;align-items:center}.button-small{white-space:nowrap}@media(max-width:520px){.deal-card-real{grid-template-columns:1fr}.deal-actions{justify-content:flex-start}}
</style></head><body><main class="my-deals"><div class="deals-head"><div><div class="eyebrow">XWADDA.KE · WORKSPACE</div><h1>My deals</h1><p class="subhead">Current agreements linked to your account.</p></div><a class="button button-outline" href="index.php">← Workspace</a></div><?php if(isset($_GET['created'])):?><div class="notice-real">Deal draft created. The invited seller has been emailed the terms.</div><?php elseif(isset($_GET['invite'])):?><div class="notice-real">We could not send the invitation email. Check your hosting mail setup and try again.</div><?php endif;?><?php if(!$deals):?><div class="empty-deals">You do not have any saved deals yet. Start one from the workspace dashboard.</div><?php else:foreach($deals as $d):$buyer=((int)$d['buyer_id']===(int)$user['id']);?><article class="deal-card-real"><div><h3><?=e($d['title'])?></h3><p><?=e($d['currency'])?> <?=number_format(((int)$d['amount_minor'])/100,2)?> · buyer fee <?=e($d['currency'])?> <?=number_format(((int)$d['fee_minor'])/100,2)?> · <?= $buyer?'Buyer':'Seller'?></p><p>Other party: <?=e($buyer?($d['seller_name']??$d['seller_email']):($d['buyer_name']??'—'))?> · Created <?=e($d['created_at'])?></p><div class="status-text"><?=e(str_replace('_',' ',$d['status']))?></div></div><div class="deal-actions"><?php if($buyer && $d['status']==='awaiting_payment'):?><a class="button button-small" href="pay.php?deal=<?=rawurlencode($d['public_id'])?>"><?= $d['currency']==='KES'?'Pay with M-PESA →':'Pay with USDT →' ?></a><?php endif;?></div></article><?php endforeach;endif;?></main><footer class="site-copyright">© <?=gmdate('Y')?> XWADDA.KE. All rights reserved.</footer></body></html>
